#!/usr/bin/env bash

# Prune the unused locales (i.e. everything but English and French) from the
# `onlyoffice-editor` npm package (i.e. `client/node_modules/onlyoffice-editor`).
#
# This package is huge (~600MB), most of which is per-language data (the UI
# translations and the spell-check dictionaries). OnlyOffice falls back to English
# for any missing locale and disables spell-check for languages without a dictionary,
# so this only affects non-English/French users (editor UI displayed in English,
# spell-checking not available).
#
# This script is meant to be run in CI right after each `npm install` (see
# `.github/workflows/ci-web.yml`), it is idempotent so it can also be run locally.
#
# Usage: bash .github/scripts/prune_node_modules_onlyoffice.sh [<package-dir>]

set -eu

SCRIPT_DIR=$(cd "$(dirname "$0")" && pwd)
PACKAGE_DIR="${1:-$SCRIPT_DIR/../../client/node_modules/onlyoffice-editor}"

if [ ! -d "$PACKAGE_DIR" ]; then
    echo "Nothing to prune: '$PACKAGE_DIR' does not exist (is the package installed ?)"
    exit 0
fi

# UI translations, named after the short locale code requested by the editor
# (e.g. `en.json`, see `longLocaleCodeToShort` in `client/src/services/translation.ts`)
LOCALE_DIRS=(
    # cSpell:disable
    "web-apps/apps/documenteditor/main/locale"
    "web-apps/apps/documenteditor/embed/locale"
    "web-apps/apps/documenteditor/forms/locale"
    "web-apps/apps/presentationeditor/main/locale"
    "web-apps/apps/presentationeditor/embed/locale"
    "web-apps/apps/spreadsheeteditor/main/locale"
    "web-apps/apps/spreadsheeteditor/embed/locale"
    # cSpell:enable
)

SIZE_BEFORE=$(du -sh "$PACKAGE_DIR" | cut -f1)

for locale_dir in "${LOCALE_DIRS[@]}"; do
    dir="$PACKAGE_DIR/$locale_dir"
    [ -d "$dir" ] || continue
    # Keep only the English and French translations
    find "$dir" -maxdepth 1 -type f -name '*.json' ! -name 'en.json' ! -name 'fr.json' -delete
done

# Spell-check dictionaries, named after the long locale code (e.g. `en_US`)
for dictionary_dir in "$PACKAGE_DIR/dictionaries"/*/; do
    [ -d "$dictionary_dir" ] || continue
    # Keep only the English and French dictionaries
    case "$(basename "$dictionary_dir")" in
    en_US | fr_FR) ;;
    *) rm -r "$dictionary_dir" ;;
    esac
done

SIZE_AFTER=$(du -sh "$PACKAGE_DIR" | cut -f1)
echo "Pruned OnlyOffice locales in '$PACKAGE_DIR': $SIZE_BEFORE -> $SIZE_AFTER"
